import {icon} from './icons.js';
import {photoFor,photoForTheme,photoAttributes,photoTone} from './photography.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plural=n=>`${n} ${n===1?'passage':'passages'}`;
const typeLabel=type=>({quran:'Qur’an',dua:'Du’a',hadith:'Hadith',story:'Story'})[type]||'Passage';
export function personalPost(id,find){return find(id)||(/^(q|dua)-\d+-\d+$/.test(id)?{id,type:id.startsWith('dua-')?'dua':'quran',title:'Saved ayah',reference:'Qur’an',verse:id.replace(/^(q|dua)-/,'').replace('-',':'),pending:true}:null);}
function photo(post){return post&&!post.pending?photoFor(post):photoForTheme('river');}
function image(post,cls=''){const p=photo(post);return `<img class="${cls}" ${photoAttributes(p,'160px')} alt="" loading="lazy"/>`;}
export function libraryEntry(post,{folder,visit}={}){
  const action=visit?'resume-passage':'open-post';
  return `<article class="library-entry" data-post-id="${esc(post.id)}"><button class="library-entry-open" data-action="${action}" data-id="${esc(post.id)}">${image(post)}<span class="library-entry-copy"><span class="library-entry-type">${typeLabel(post.type)}${visit&&!visit.dayOnly?` · ${new Date(visit.at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}`:''}</span><strong>${esc(post.title)}</strong><span>${esc(post.reference)} · ${esc(post.verse)}</span>${post.text?`<span class="library-entry-excerpt">${esc(post.text)}</span>`:''}</span></button><button class="library-entry-action" data-action="${folder?'remove-member':'organise'}" data-id="${esc(post.id)}" ${folder?`data-folder="${esc(folder.id)}"`:''} aria-label="${folder?'Remove from this collection':'Organise '+esc(post.title)}">${icon(folder?'close':'folder')}</button></article>`;
}
function empty(title,copy,button='Explore the feed',action='navigate'){
  return `<div class="personal-empty">${icon('bookmark')}<h2>${title}</h2><p>${copy}</p><button class="text-button" data-action="${action}">${button} ${icon('arrow')}</button></div>`;
}
function dayLabel(at){const d=new Date(at),now=new Date(),yesterday=new Date();yesterday.setDate(now.getDate()-1);if(d.toDateString()===now.toDateString())return 'Today';if(d.toDateString()===yesterday.toDateString())return 'Yesterday';return d.toLocaleDateString([],{day:'numeric',month:'long',year:d.getFullYear()!==now.getFullYear()?'numeric':undefined});}
export function renderPersonalLibrary({state,personal,findPost,legacyResume}){
  const get=id=>personalPost(id,findPost),folder=personal.collection(state.personalCollection);
  const resume=personal.resume||(legacyResume?{...legacyResume,surface:'reader'}:null),resumePost=resume&&get(resume.id);
  const tabs=[['saved','Saved',state.saved.length],['collections','Collections',personal.collections.length],['history','History',personal.history.length],['liked','Liked',state.liked.length],['notes','Notes',Object.values(state.notes).filter(n=>n?.text).length]];
  let body='';
  if(folder){
    const cover=get(folder.ids[0]),p=photo(cover);
    body=`<button class="personal-back" data-action="library-tab" data-id="collections">${icon('arrow')} All collections</button><div class="personal-folder-hero" style="${photoTone(p)}">${image(cover)}<div><span>Your collection · ${plural(folder.ids.length)}</span><h2>${esc(folder.name)}</h2></div>${icon('folder')}</div><div class="personal-toolbar"><button class="text-button" data-action="add-passages" data-id="${folder.id}">${icon('plus')} Add passages</button><span></span><button class="text-button" data-action="rename-folder" data-id="${folder.id}">Rename</button><button class="text-button" data-action="delete-folder" data-id="${folder.id}">Delete</button></div><div class="library-entries">${folder.ids.slice(0,state.libraryLimit).map(get).filter(Boolean).map(p=>libraryEntry(p,{folder})).join('')}</div>${folder.ids.length?more(folder.ids.length,state.libraryLimit):empty('Make room for what matters.','Add saved passages to this collection.','Choose from saved','add-passages')}`;
  }else if(state.libraryTab==='collections'){
    body=personal.collections.length?`<div class="personal-collections">${personal.collections.map(c=>{const post=get(c.ids[0]),p=photo(post);return `<button class="personal-collection" data-action="open-folder" data-id="${c.id}" data-post-id="${esc(post?.id||'')}" style="${photoTone(p)}">${image(post)}<span class="personal-collection-icon">${icon('folder')}</span><span class="personal-collection-copy"><strong>${esc(c.name)}</strong><span>${plural(c.ids.length)}</span></span>${icon('arrow')}</button>`;}).join('')}</div><button class="personal-new-folder" data-action="new-folder">${icon('plus')} Create another collection</button>`:empty('A collection, just for you.','Gather passages for memorisation, a quiet morning, or something you want to return to.','Create a collection','new-folder');
  }else if(state.libraryTab==='history'){
    const groups=new Map();for(const visit of personal.history.slice(0,state.libraryLimit)){const post=get(visit.id);if(!post)continue;const label=dayLabel(visit.at);if(!groups.has(label))groups.set(label,[]);groups.get(label).push({visit,post});}
    body=`<div class="personal-history-tools"><p>${personal.enabled?'Your recent visits, newest first.':'History is paused.'}<small>Up to 300 passages · stored on this device</small></p><button class="text-button" data-action="history-settings">${icon('settings')} Manage</button></div>${groups.size?[...groups].map(([day,rows])=>`<section class="history-day"><h2>${day}</h2>${rows.map(({visit,post})=>libraryEntry(post,{visit})).join('')}</section>`).join('')+more(personal.history.length,state.libraryLimit):empty('Your next visit starts here.',personal.enabled?'Passages appear here after you spend a moment reading them.':'Resume history in Manage whenever you want to keep recent visits.')}`;
  }else if(state.libraryTab==='notes'){
    const list=Object.keys(state.notes).filter(id=>state.notes[id]?.text).map(get).filter(Boolean);
    body=list.length?list.slice(0,state.libraryLimit).map(p=>`<article class="personal-note"><span class="library-entry-type">Private reflection · ${esc(p.verse)}</span><h2>${esc(p.title)}</h2><p>${esc(state.notes[p.id].text)}</p><button class="text-button" data-action="reflect" data-id="${p.id}">Continue writing ${icon('pen')}</button><button class="text-button" data-action="open-post" data-id="${p.id}">Read passage ${icon('arrow')}</button></article>`).join('')+more(list.length,state.libraryLimit):empty('A space for your thoughts.','Tap Reflect on a passage to begin. Your writing stays on this device.');
  }else{
    const list=(state.libraryTab==='liked'?state.liked:state.saved).map(get).filter(Boolean);
    body=list.length?`<div class="personal-list-heading"><span>${plural(list.length)}</span><span>Tap ${icon('folder')} to organise</span></div><div class="library-entries">${list.slice(0,state.libraryLimit).map(p=>libraryEntry(p)).join('')}</div>${more(list.length,state.libraryLimit)}`:empty(state.libraryTab==='liked'?'What stays with you.':'Keep a little light.','Save a passage from the feed and it will be waiting here.');
  }
  return `<section class="personal-library" aria-label="Your personal library"><header class="personal-heading"><div><span class="personal-kicker">A space of your own</span><h1>Your library</h1><p>Keep what speaks to you. Return when you need it.</p></div><button class="personal-create" data-action="new-folder" aria-label="Create a collection">${icon('plus')}<span>New collection</span></button></header>${resumePost&&!folder&&state.libraryTab==='saved'?`<button class="personal-resume" data-post-id="${esc(resumePost.id)}" data-action="resume-passage" data-id="${esc(resumePost.id)}" style="${photoTone(photo(resumePost))}">${image(resumePost)}<span><span class="personal-kicker">Continue reading</span><strong>${esc(resumePost.title)}</strong><small>${esc(resumePost.verse)} · ${resume.surface==='reader'?'Surah reader':'Your feed'}</small></span>${icon('arrow')}</button>`:''}<div class="personal-tabs" role="tablist" aria-label="Library sections">${tabs.map(([id,label,count])=>`<button class="${state.libraryTab===id?'active':''}" role="tab" aria-selected="${state.libraryTab===id}" data-action="library-tab" data-id="${id}">${label}<span>${count}</span></button>`).join('')}</div>${body}<p class="personal-privacy">${icon('shield')} Your library stays in this browser. No account needed.</p></section>`;
}
function more(total,limit){return total>limit?`<button class="personal-load-more" data-action="library-more">Show more ${icon('down')}</button>`:'';}
